module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg load;
    reg [9:0] data;
    wire tc;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .load(load),
        .data(data),
        .tc(tc)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    integer errors = 0;
    reg [9:0] expected_data;

    initial begin
        // Initialize inputs
        load = 0;
        data = 10'd0;

        @(posedge clk);
        #1;

        // Test 1: Reset / Initial state - tc should be high or stable if 0 loaded
        // Let's load 0 and check if tc is immediately asserted
        load = 1;
        data = 10'd0;
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            $display("Error: load 0 failed to assert tc immediately. Got tc = %b", tc);
            errors = errors + 1;
        end

        // Test 2: Countdown test with small value (e.g., 3)
        load = 1;
        data = 10'd3;
        @(posedge clk);
        #1;
        load = 0;
        // At this point, counter loaded with 3. 
        // Clock 1: should decrement to 2, tc = 0
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            $display("Error: tc should be 0 during countdown (count=2). Got tc = %b", tc);
            errors = errors + 1;
        end

        // Clock 2: should decrement to 1, tc = 0
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            $display("Error: tc should be 0 during countdown (count=1). Got tc = %b", tc);
            errors = errors + 1;
        end

        // Clock 3: should decrement to 0, tc = 1
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            $display("Error: tc should be 1 when count reaches 0. Got tc = %b", tc);
            errors = errors + 1;
        end

        // Clock 4: should stay 0 and tc should stay 1 (stop counting)
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            $display("Error: tc should stay 1 after reaching 0. Got tc = %b", tc);
            errors = errors + 1;
        end

        // Test 3: Reload during countdown
        load = 1;
        data = 10'd5;
        @(posedge clk);
        #1;
        load = 0;
        // Count is 5. Wait 2 cycles (count becomes 3)
        @(posedge clk);
        @(posedge clk);
        #1;
        // Now reload with 2 while counting
        load = 1;
        data = 10'd2;
        @(posedge clk);
        #1;
        load = 0;
        // Should take 2 cycles from now to reach 0
        // Cycle 1 after load: count = 1, tc = 0
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            $display("Error: reload during countdown failed (expected tc=0). Got tc = %b", tc);
            errors = errors + 1;
        end

        // Cycle 2 after load: count = 0, tc = 1
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            $display("Error: reload during countdown failed (expected tc=1). Got tc = %b", tc);
            errors = errors + 1;
        end

        // Final Result reporting
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
